using System;using System.IO;using Unity.AI.Assistant.Agent.Dynamic.Extension.Editor;
public static class PaletteRuntimeTests89 {
 public static void Main(string[] args){byte[] rgb={254,237,216,252,228,209,80,120,160};int[] edges={1,0};int checks=0;foreach(double floor in new[]{.1,.55,.72,1.0}){var p=PaletteRuntime89.Build(rgb,edges,3,floor);if(Math.Abs(p.labRatio*p.labRatio*p.labRatio-floor)>1e-12)throw new Exception("89 floor unit adapter");for(int i=0;i<rgb.Length/3;i++)for(int c=0;c<3;c++)if(p.rgb8[(i*3+2)*3+c]!=rgb[3*i+c])throw new Exception("89 source endpoint");checks++;}try{PaletteRuntime89.Build(rgb,edges,3,0);throw new Exception("89 impossible black contrast accepted");}catch(ArgumentException){checks++;}Console.WriteLine("checks="+checks);if(args.Length==4){var refs=File.ReadAllBytes(args[0]);var raw=File.ReadAllBytes(args[1]);var pairs=new int[raw.Length/4];Buffer.BlockCopy(raw,0,pairs,0,raw.Length);double f=Double.Parse(args[2],System.Globalization.CultureInfo.InvariantCulture);var p=PaletteRuntime89.Build(refs,pairs,3,f);File.WriteAllBytes(args[3],p.rgb8);Console.WriteLine("maxCodeError="+p.maxCodeError+";roundingChanges="+p.roundingChanges);}}
}
